{"clips": [
  {
    "id": "C1",
    "weakest_point": "The long, static interrogation in the middle loses momentum, and the ending is a triumphant reaction rather than an unresolved peak.",
    "hook": {
      "score": 3,
      "reason": "The threat about the county gaol is cruel and lands early, but it is a static close-up of eyes and the referent ('him') is unclear without context."
    },
    "cliffhanger": {
      "score": 2,
      "reason": "Ends on the Lord's grin and a rhetorical question after he has already won the exchange; the conflict is resolved in his favor and no forward question burns."
    },
    "questions": [
      {"q": "Who is the 'him' the Lord wants sent to gaol?", "type": "confusion"},
      {"q": "Who is the 'she' who drew herbs around the bed?", "type": "confusion"},
      {"q": "Will the maid be forced to testify against her?", "type": "intrigue"}
    ],
    "standalone": {
      "score": 3,
      "reason": "Followable as a powerful man interrogating a servant, but the stakes and identities (the child, the accused woman) are murky."
    },
    "emotion": {
      "score": 3,
      "reason": "The maid's terror is visceral and the Lord's cruelty is chilling, but the extended Q&A numbs the impact."
    },
    "want_next": {
      "score": 3,
      "reason": "The trial is implied but not sharply telegraphed; the ending feels more like a scene-ender than an episode-ender."
    },
    "ad_policy": {
      "level": "none",
      "category": "none",
      "reason": "No on-screen violence, blood, or sexual content; only verbal threats and crying."
    },
    "one_line_verdict": "A cold, cruel interrogation that drags and ends on a villainous mic-drop instead of a burning question."
  },
  {
    "id": "C2",
    "weakest_point": "The final fade to black on the maid weeping is a reaction after the conflict, not a cliffhanger.",
    "hook": {
      "score": 4,
      "reason": "'That is witchcraft' is a lethal, shocking pronouncement delivered in the first second with enough visceral weight to stop a scroll, though it needs a beat to register what 'that' refers to."
    },
    "cliffhanger": {
      "score": 2,
      "reason": "The scene fades to darkness on the maid's grief after the Lord has delivered his ultimatum; the tension has collapsed into sorrow rather than cutting at a peak."
    },
    "questions": [
      {"q": "Will Prudence give the false testimony at the trial?", "type": "intrigue"},
      {"q": "What happens to Lady Juliana?", "type": "intrigue"},
      {"q": "Who is Toby and how did she save him?", "type": "confusion"}
    ],
    "standalone": {
      "score": 4,
      "reason": "Zero-context viewers can follow a Duke coercing a maid to frame a healer for witchcraft before a magistrate; the power dynamic and stakes are legible."
    },
    "emotion": {
      "score": 4,
      "reason": "The maid's collapse, groveling, and heartbreak over her brother deliver a gut-punch of injustice and despair."
    },
    "want_next": {
      "score": 4,
      "reason": "The explicit line 'Save your tears for the trial' points directly to the next episode and the coerced testimony."
    },
    "ad_policy": {
      "level": "none",
      "category": "none",
      "reason": "No on-screen violence, blood, or sexual content; only verbal coercion and a crying collapse."
    },
    "one_line_verdict": "The clearest, most emotionally brutal coercion scene, undercut only by a fading, reactive ending."
  },
  {
    "id": "C3",
    "weakest_point": "The opening line is the tail end of a previous argument, and the mid-clip cut to a courtroom resets the momentum instead of building it.",
    "hook": {
      "score": 2,
      "reason": "'Praying... or chanting?' is a sinister question, but without context it is confusing who is speaking or why it matters; it needs the preceding conversation to land."
    },
    "cliffhanger": {
      "score": 2,
      "reason": "It ends on a witness answering a preliminary question ('Yes, Your Honor') after the gavel slam; the dramatic peak has passed and no specific burning question is left."
    },
    "questions": [
      {"q": "Who is praying or chanting, and why does it matter?", "type": "confusion"},
      {"q": "Why does the scene suddenly cut to a courtroom?", "type": "confusion"},
      {"q": "What will Prudence say about Lady Juliana?", "type": "intrigue"}
    ],
    "standalone": {
      "score": 3,
      "reason": "The courtroom payoff helps clarify the stakes, but the disjointed opening and mid-clip jump make it harder to follow than C2."
    },
    "emotion": {
      "score": 3,
      "reason": "The maid's breakdown and the trial tension are effective, but the editing fractures the emotional build."
    },
    "want_next": {
      "score": 3,
      "reason": "The trial creates curiosity, but the soft ending on a witness stand doesn't create an urgent need to tap."
    },
    "ad_policy": {
      "level": "none",
      "category": "none",
      "reason": "No on-screen violence, blood, or sexual content; a gavel slam is not physical harm to a person."
    },
    "one_line_verdict": "A disjointed two-parter that sacrifices a sharp hook and ending for a courtroom tease."
  }
],
  "best": "C2",
  "best_why": "It has the strongest hook, the clearest standalone stakes, and the most brutal emotional beat, pointing directly to the next episode."
}
